<?php
declare(strict_types=1);
if (!defined('SW_APP')) { http_response_code(404); exit; }
function head(string $title): void { ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=h($title)?> · SORTEOWEB</title><link rel="stylesheet" href="assets/style.css?v=<?=h(SW_VERSION)?>"><script src="assets/app.js?v=<?=h(SW_VERSION)?>" defer></script></head><?php }
function render_notice(string $message,string $kind='success'): void { $kind=in_array($kind,['success','error','warning','info'],true)?$kind:'info'; ?><div role="<?=$kind==='error'||$kind==='warning'?'alert':'status'?>" class="notice <?=h($kind)?>" data-notice><span class="notice-text"><?=h($message)?></span><button type="button" class="notice-close" data-dismiss-notice aria-label="Cerrar mensaje" title="Cerrar mensaje">×</button></div><?php }
function notice(): void { $f=$_SESSION['flash']??null;unset($_SESSION['flash']);if($f)render_notice($f[0],$f[1]); }
function render_message(string $title,string $message): void { head($title); ?><body class="login"><section class="login-card"><div class="brand"><span class="logo">S</span><strong>SORTEOWEB</strong></div><h1><?=h($title)?></h1><?php render_notice($message,'error'); ?><a class="btn primary" href="index.php?admin=1">Volver a intentar</a></section></body></html><?php }
function render_login(): void { head('Iniciar sesión'); ?><body class="login"><section class="login-card"><div class="brand"><span class="logo">S</span><strong>SORTEOWEB</strong></div><p class="eyebrow">ADMINISTRACIÓN</p><h1>Bienvenido</h1><p>Accede al panel para gestionar tus sorteos.</p><?php notice(); ?><form method="post" action="index.php?admin=1"><?=csrf()?><input type="hidden" name="action" value="login"><label>Usuario<input name="username" required maxlength="120" autocomplete="username" autofocus></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password" maxlength="256"></label><button class="btn primary full" type="submit">Iniciar sesión</button></form><small class="muted">SORTEOWEB · v<?=SW_VERSION?></small></section></body></html><?php }
function url(string $page,array $params=[]): string { return 'index.php?'.http_build_query(['page'=>$page]+$params); }
function form_action(string $action,string $id,string $label,string $class='secondary',?string $pid=null,string $confirm=''): void { ?><form method="post" class="inline" <?=$confirm!==''?'data-confirm="'.h($confirm).'"':''?>><?=csrf()?><input type="hidden" name="action" value="<?=h($action)?>"><input type="hidden" name="raffle_id" value="<?=h($id)?>"><?php if($pid!==null): ?><input type="hidden" name="participant_id" value="<?=h($pid)?>"><?php endif; ?><button class="btn <?=h($class)?> small" type="submit"><?=h($label)?></button></form><?php }
function render_stat(string $label,string|int $value,string $sub=''): void { ?><div class="stat"><span><?=h($label)?></span><strong><?=h($value)?></strong><small><?=h($sub)?></small></div><?php }
function empty_state(string $title,string $subtitle): void { ?><div class="empty"><strong><?=h($title)?></strong><p><?=h($subtitle)?></p></div><?php }
function photo(string $id,int|string|null $slot,bool $moneyDefault=false): void { if($moneyDefault): ?><img class="thumb" src="assets/premio-dinero.svg" alt="Foto del premio" loading="lazy"><?php elseif($slot): ?><img class="thumb" src="index.php?photo=<?=h($id)?>&amp;slot=<?=(int)$slot?>&amp;size=thumb" alt="Foto del premio" loading="lazy"><?php else: ?><span class="thumb placeholder">▧</span><?php endif; }
function render_panel(array $u,string $page): void {
    $labels=['sorteos'=>'Sorteos','participantes'=>'Participantes','ganadores'=>'Ganadores','ingresos'=>'Ingresos','cuenta'=>'Mi cuenta'];$icons=['sorteos'=>'▤','participantes'=>'♙','ganadores'=>'☆','ingresos'=>'$','cuenta'=>'⚙'];
    head($labels[$page]); ?><body><div class="shell"><button type="button" id="sidebar-overlay" class="sidebar-overlay" aria-label="Cerrar menú lateral" tabindex="-1" hidden></button><aside class="sidebar" id="sidebar" aria-label="Menú administrativo"><div class="sidebar-head"><a href="index.php?admin=1" class="brand"><span class="logo">S</span><span><strong>SORTEOWEB</strong><small>Panel administrativo</small></span></a><button type="button" class="sidebar-close" id="sidebar-close" aria-label="Cerrar menú lateral" title="Cerrar menú">×</button></div><div class="nav-caption">GESTIÓN</div><nav><?php foreach($labels as $k=>$label): ?><a href="<?=h(url($k))?>" class="nav-link <?=$page===$k?'active':''?>" <?=$page===$k?'aria-current="page"':''?>><span class="nav-icon"><?=h($icons[$k])?></span><?=h($label)?></a><?php endforeach; ?></nav><div class="sidebar-bottom"><div class="person"><strong><?=h($u['username'])?></strong><small>Administrador</small></div><form method="post" action="index.php?admin=1"><?=csrf()?><input type="hidden" name="action" value="logout"><button class="btn logout full" type="submit">Cerrar sesión</button></form><small>v<?=SW_VERSION?></small></div></aside><main><header class="topbar"><button type="button" class="menu-toggle btn secondary" aria-label="Abrir menú lateral" aria-controls="sidebar" aria-expanded="false" id="menu-toggle">☰</button><span>Administración <b> / <?=h($labels[$page])?></b></span><span class="avatar"><?=h(strtoupper(substr($u['username'],0,1)))?></span></header><div class="content"><?php notice();require __DIR__.'/modules/'.$page.'.php'; ?></div></main></div></body></html><?php }
